Base.metadata.create_all(engine)
Session = sessionmaker(bind=engine)
session = Session()

# Helper function to convert Gregorian to Hijri
def gregorian_to_hijri(date):
    return hijri_converter.Gregorian(date.year, date.month, date.day).to_hijri()

# Route for home page
@app.route('/')
def index():
    if 'user_id' in session:
        user = session['user_id']
        incomes = session.query(Income).filter_by(user_id=user).all()
        expenses = session.query(Expense).filter_by(user_id=user).all()
        zakat_due = session.query(ZakatPayment).filter_by(user_id=user, paid=False).all()
        return render_template('index.html', incomes=incomes, expenses=expenses, zakat_due=zakat_due)
    else:
        return redirect(url_for('login'))

# Route for login
@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']
        user = session.query(User).filter_by(username=username).first()
        if user and check_password_hash(user.password, password):
            session['user_id'] = user.id
            return redirect(url_for('index'))
        else:
            flash('Invalid username or password')
    return render_template('login.html')

# Route for logout
@app.route('/logout')
def logout():
    session.pop('user_id', None)
    return redirect(url_for('login'))

# Route for adding income
@app.route('/add_income', methods=['POST'])
def add_income():
    if 'user_id' in session:
        user_id = session['user_id']
        amount = float(request.form['amount'])
        date = datetime.strptime(request.form['date'], '%Y-%m-%d %H:%M:%S')
        income = Income(amount=amount, date=date, user_id=user_id)
        session.add(income)
        session.commit()
        return redirect(url_for('index'))
    else:
        return redirect(url_for('login'))

# Route for adding expense
@app.route('/add_expense', methods=['POST'])
def add_expense():
    if 'user_id' in session:
        user_id = session['user_id']
        amount = float(request.form['amount'])
        date = datetime.strptime(request.form['date'], '%Y-%m-%d %H:%M:%S')
        income_id = int(request.form['income_id'])
        expense = Expense(amount=amount, date=date, user_id=user_id, income_id=income_id)
        session.add(expense)
        session.commit()
        return redirect(url_for('index'))
    else:
        return redirect(url_for('login'))

# Route for calculating zakat
@app.route('/calculate_zakat', methods=['POST'])
def calculate_zakat():
    if 'user_id' in session:
        user_id = session['user_id']
        incomes = session.query(Income).filter_by(user_id=user_id).order_by(Income.date.desc()).all()
        total_amount = 0
        zakat_due = []

        for income in incomes:
            total_amount += income.amount
            if total_amount >= 2.5:
                # Calculate zakat for the amount that has been in possession for more than 1 hijri year
                hijri_date = gregorian_to_hijri(income.date)
                if hijri_date.year > hijri_date.now().year + 1:
                    zakat_amount = (total_amount * 0.025)
                    zakat_due.append((income, zakat_amount))
                    total_amount -= zakat_amount

        # Save zakat payments
        for income, zakat_amount in zakat_due:
            zakat_payment = ZakatPayment(amount=zakat_amount, income_id=income.id, user_id=user_id)
            session.add(zakat_payment)
            session.commit()

        return jsonify({'zakat_due': zakat_due})
    else:
        return redirect(url_for('login'))

# Route for marking zakat as paid
@app.route('/mark_zakat_as_paid/<int:zakat_id>', methods=['POST'])
def mark_zakat_as_paid(zakat_id):
    if 'user_id' in session:
        zakat_payment = session.query(ZakatPayment).get(zakat_id)
        if zakat_payment:
            zakat_payment.paid = True
            session.commit()
            return jsonify({'status': 'success'})
        else:
            return jsonify({'status': 'failure'})
    else:
        return redirect(url_for('login'))

# Route for marking all zakat as paid
@app.route('/mark_all_zakat_as_paid', methods=['POST'])
def mark_all_zakat_as_paid():
    if 'user_id' in session:
        user_id = session['user_id']
        zakat_payments = session.query(ZakatPayment).filter_by(user_id=user_id, paid=False).all()
        for zakat_payment in zakat_payments:
            zakat_payment.paid = True
            session.commit()
        return jsonify({'status': 'success'})
    else:
        return redirect(url_for('login'))

if __name__ == '__main__':
    app.run(debug=True)
```

