from math import sqrt

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    for i in range(2, int(sqrt(num)) + 1):
        if num % i == 0:
            return False
    return True

def prime_fib(n: int) -> int:
    count, a, b = 0, 0, 1
    while True:
        fib_num = a
        a, b = b, a + b
        if is_prime(fib_num):
            count += 1
            if count == n:
                return fib_num
