```csharp
using Xunit;

public class GroceryCostCalculatorTests
{
    [Fact]
    public void CalculateAverageMonthlyCost_WithValidData_ReturnsCorrectAverage()
    {
        // Arrange
        var calculator = new GroceryCostCalculator();
        decimal[] yearlyGroceryCosts = { 1200m, 1300m, 1400m, 1500m, 1600m, 1700m, 1800m, 1900m, 2000m, 2100m, 2200m, 2300m };

        // Act
        double result = calculator.CalculateAverageMonthlyCost(yearlyGroceryCosts);

        // Assert
        Assert.Equal(1750.0, result);
    }

    [Fact]
    public void CalculateAverageMonthlyCost_WithEmptyArray_ThrowsArgumentException()
    {
        // Arrange
        var calculator = new GroceryCostCalculator();
        decimal[] yearlyGroceryCosts = {};

        // Act & Assert
        Assert.Throws<ArgumentException>(() => calculator.CalculateAverageMonthlyCost(yearlyGroceryCosts));
    }

    [Fact]
    public void CalculateAverageMonthlyCost_WithNullArray_ThrowsArgumentException()
    {
        // Arrange
        var calculator = new GroceryCostCalculator();

        // Act & Assert
        Assert.Throws<ArgumentException>(() => calculator.CalculateAverageMonthlyCost(null));
    }

    [Fact]
    public void CalculateAverageMonthlyCost_WithSingleElement_ReturnsThatValue()
    {
        // Arrange
        var calculator = new GroceryCostCalculator();
        decimal[] yearlyGroceryCosts = { 1200m };

        // Act
        double result = calculator.CalculateAverageMonthlyCost(yearlyGroceryCosts);

        // Assert
        Assert.Equal(1200.0, result);
    }
}
```

### Explanation:
1. **CalculateAverageMonthlyCost_WithValidData_ReturnsCorrectAverage**: This test checks if the method correctly calculates the average when given valid data.
2. **CalculateAverageMonthlyCost_WithEmptyArray_ThrowsArgumentException**: This test ensures that the method throws an `ArgumentException` when given an empty array.
3. **CalculateAverageMonthlyCost_WithNullArray_ThrowsArgumentException**: This test ensures that the method throws an `ArgumentException` when given a null array.
4. **CalculateAverageMonthlyCost_WithSingleElement_ReturnsThatValue**: This test checks if the method returns the single element when given an array with only one element.

These tests cover different scenarios to ensure the method behaves as expected under various conditions.

