```python
def check_dict_case(dict):
    if not dict:
        return False

    lower_case = set()
    upper_case = set()

    for key in dict.keys():
        if not isinstance(key, str):
            return False
        if key.islower():
            lower_case.add(key)
        elif key.isupper():
            upper_case.add(key)
        else:
            return False

    return len(lower_case) == len(dict) or len(upper_case) == len(dict)
```

```python
def fib4(n: int):
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the base cases
    a, b, c, d = 0, 0, 2, 0

    # Compute the n-th element iteratively
    for _ in range(4, n + 1):
        a, b, c, d = b, c, d, a + b + c + d

    return d
```

