```javascript
// ocr.js
const Tesseract = require('tesseract.js');
const fs = require('fs');

async function extractTextFromImage(imagePath) {
    const { data: { text } } = await Tesseract.recognize(
        imagePath,
        'eng',
        { logger: m => console.log(m) }
    );
    return text;
}

module.exports = extractTextFromImage;
```

