// app.js
const express = require('express');
const mongoose = require('mongoose');
const GameResult = require('./db').GameResult;
const web3 = require('./web3');

const app = express();
app.use(express.json());

app.get('/results', async (req, res) => {
    const results = await GameResult.find().sort({ timestamp: -1 }).limit(10);
    res.json(results);
});

app.post('/race', async (req, res) => {
    const imagePath = req.body.imagePath;
    await processRaceResults(imagePath);
    res.status(200).send('Race results processed.');
});

app.listen(3001, () => {
    console.log('Server running on port 3001');
});
