**Frontend (React.js)**

```javascript
// App.js
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
    const [results, setResults] = useState([]);

    useEffect(() => {
        const fetchResults = async () => {
            const response = await axios.get('http://localhost:3001/results');
            setResults(response.data);
        };
        fetchResults();
    }, []);

    return (
        <div>
            <h1>Mariokart Race Results</h1>
            <ul>
                {results.map(result => (
                    <li key={result._id}>
                        {result.winner} placed {result.gameId} at {result.timestamp.toISOString()}
                    </li>
                ))}
            </ul>
        </div>
    );
}

export default App;
