Certainly! Below is an example of how you might write a Node.js test to validate multiple JSON contract files using a testing framework like Jest. We'll assume you have a directory structure similar to the one described in the Laravel example.

### Directory Structure
```
project-root/
├── contracts/
│   ├── users-contract.json
│   └── posts-contract.json
├── src/
│   └── contracts-test.js
└── package.json
```

### `package.json`
Make sure your `package.json` includes the necessary dependencies:
```json
{
  "name": "your-project-name",
  "version": "1.0.0",
  "main": "index.js",
  "scripts": {
    "test": "jest"
  },
  "dependencies": {},
  "devDependencies": {
    "jest": "^27.0.0"
  }
}
```

### `src/contracts-test.js`
Here is the Node.js test file that will test each contract file in the `contracts` directory:

```javascript
const fs = require('fs');
const path = require('path');

// Function to read and parse a JSON file
function readJsonFile(filePath) {
  const content = fs.readFileSync(filePath, 'utf8');
  return JSON.parse(content);
}

// Function to test a single contract file
function testContract(contractFile) {
  const contract = readJsonFile(contractFile);

  expect(contract.endpoints).toBeDefined();
  expect(contract.dataModels).toBeDefined();

  Object.keys(contract.endpoints).forEach((endpoint) => {
    const response = fetch(`http://localhost:3000/${endpoint}`); // Adjust the URL as needed
    expect(response.status).toBe(200);

    const data = response.json();
    expect(Array.isArray(data)).toBe(true);

    const dataModel = getDataModel(endpoint, contract);
    expect(dataModel).toBeTruthy();

    data.forEach(item => {
      expect(item.id).toBeDefined();
      expect(item.type).toBeDefined();

      const properties = dataModel.properties;
      Object.keys(properties).forEach(property => {
        expect(item[property]).toBeDefined();
        expect(typeof item[property]).toBe(properties[property]);
      });
    });
  });
}

// Function to get the data model for a specific endpoint
function getDataModel(endpoint, contract) {
  const endpointName = endpoint.split('/').pop();
  return contract.dataModels[endpointName];
}

// Main test function
describe('Contract Test', () => {
  const contractsDirectory = path.join(__dirname, '../contracts');

  fs.readdir(contractsDirectory, (err, files) => {
    if (err) throw err;

    files.forEach(file => {
      if (file.endsWith('.json')) {
        const filePath = path.join(contractsDirectory, file);
        testContract(filePath);
      }
    });
  });
});
```

### Explanation
1. **Reading JSON Files**: The `readJsonFile` function reads and parses a JSON file.
2. **Testing a Single Contract**: The `testContract` function checks if the contract has the required keys (`endpoints` and `dataModels`) and then iterates over each endpoint to make a request and validate the response.
3. **Getting Data Model**: The `getDataModel` function retrieves the data model for a specific endpoint from the contract.
4. **Main Test Function**: The main test function reads all files in the `contracts` directory and runs the `testContract` function for each JSON file.

### Running the Tests
To run the tests, you can use the following command in your terminal:
```sh
npm test
```

This will execute the tests defined in `src/contracts-test.js` and report any failures or errors. Make sure your server is running and accessible at the specified URL (`http://localhost:3000` in this example).

