```javascript
const AWS = require('aws-sdk');
const SSH = require('node-ssh');
const { execSync } = require('child_process');

// Set the region where your EC2 instance is running
AWS.config.update({ region: 'us-east-1' });

// Create an EC2 client object
const ec2 = new AWS.EC2();

// Function to get the private IP address of the EC2 instance
function getInstancePrivateIP(instanceName) {
  const params = {
    Filters: [
      {
        Name: 'tag:Name',
        Values: [instanceName]
      }
    ]
  };
  return new Promise((resolve, reject) => {
    ec2.describeInstances(params, (err, data) => {
      if (err) {
        reject(err);
      } else {
        const instance = data.Reservations[0].Instances[0];
        resolve(instance.PrivateIpAddress);
      }
    });
  });
}

// Function to connect to the Docker container via SSH
async function connectToDockerContainer(instanceName, containerNameOrId) {
  try {
    const instanceIp = await getInstancePrivateIP(instanceName);
    const ssh = new SSH();
    await ssh.connect({
      host: instanceIp,
      username: 'YOUR_SSH_USERNAME',
      privateKey: 'YOUR_PRIVATE_KEY_FILE_PATH'
    });

    // Execute the Docker command to connect to the container
    const result = await ssh.execCommand(`sudo docker exec -it ${containerNameOrId} /bin/bash`);
    console.log(result.stdout);
    ssh.dispose();
  } catch (err) {
    console.error(err);
  }
}

// Main function to handle command-line arguments
(async () => {
  const instanceName = process.argv[2];
  const containerNameOrId = process.argv[3];

  if (!instanceName || !containerNameOrId) {
    console.error('Usage: node script.js <instanceName> <containerNameOrId>');
    process.exit(1);
  }

  await connectToDockerContainer(instanceName, containerNameOrId);
})();
```

### Explanation:
1. **Command-Line Arguments**: The script uses `process.argv` to get the instance name and container name passed as command-line arguments.
2. **Error Handling**: Added error handling to ensure the script exits gracefully if the required arguments are missing.
3. **Promises**: Used Promises to handle asynchronous operations more cleanly.

### Running the Script:
