class PersonHelper implements Person {
  private isLimited: boolean;
  private lacksKnowledge: boolean;
  private experiencesEmotionalStruggles: boolean;

  constructor(
    private spirit: Spirit,
    private god: God,
    isLimited: boolean = true,
