const GOOGLE_CLOUD_PROJECT_ID = process.env.GOOGLE_CLOUD_PROJECT_ID;
const GOOGLE_CLOUD_CREDENTIALS = process.env.GOOGLE_CLOUD_CREDENTIALS;

const client = new twilio(ACCOUNT_SID, AUTH_TOKEN);
const speechClient = new SpeechClient({ projectId: GOOGLE_CLOUD_PROJECT_ID, keyFilename: GOOGLE_CLOUD_CREDENTIALS });

async function makeCall(toNumber) {
  const call = await client.calls.create({
    url: `http://${process.env.HOST}:${process.env.PORT}/handle-call-connect`,
    to: toNumber,
    from: TWILIO_PHONE_NUMBER,
  });

  console.log(`Call SID: ${call.sid}`);
  return call.sid;
}
```

#### 2. `handleCallConnect()`
This function handles the connection of the call and sets up the audio stream to capture the second participant's voice.

```javascript
const express = require('express');
const app = express();
const http = require('http').createServer(app);

app.use(express.json());

app.post('/handle-call-connect', async (req, res) => {
  const callSid = req.body.callSid;
  const call = await client.calls(callSid).fetch();

  // Start the transcription stream
  const transcriptionStream = await startTranscriptionStream(callSid);

  // Send a response to Twilio indicating the call has been connected
  res.send('<Response></Response>');
});

function startTranscriptionStream(callSid) {
  return new Promise((resolve, reject) => {
    const call = client.calls(callSid).fetch();
    const transcriptionStream = call.stream({
      mediaStream: true,
      mediaStreamType: 'audio',
      mediaStreamEncoding: 'linear16',
      mediaStreamSampleRateHertz: 16000,
    });

    transcriptionStream.on('data', (event) => {
      if (event.type === 'media') {
        // Send the media data to Google Cloud Speech-to-Text
        handleMediaData(event.data);
      }
    });

    transcriptionStream.on('end', () => {
      console.log('Transcription stream ended');
      resolve(transcriptionStream);
    });

    transcriptionStream.on('error', (err) => {
      console.error('Error in transcription stream:', err);
      reject(err);
    });
  });
}

function handleMediaData(mediaData) {
  // Send the media data to Google Cloud Speech-to-Text
  const recognitionConfig = {
    encoding: 'LINEAR16',
    sampleRateHertz: 16000,
    languageCode: 'en-US',
  };

  const audio = {
    content: mediaData,
  };

  const request = {
    config: recognitionConfig,
    audio: audio,
  };

  speechClient.recognize(request)
    .then(([response]) => {
      const results = response.results;
      results.forEach(result => {
        const transcript = result.alternatives[0].transcript;
        console.log(`Transcript: ${transcript}`);
        // Send the partial transcription to the client
        sendPartialTranscription(transcript);
      });
    })
    .catch((error) => {
      console.error('Error in transcription:', error);
    });
}

function sendPartialTranscription(transcript) {
  // Send the partial transcription to the client
  // This would typically involve setting up a WebSocket or similar real-time communication mechanism
  // For simplicity, we'll just log it here
  console.log(`Sending partial transcription: ${transcript}`);
}

app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
});
```

### Client-Side Code

#### 3. `handleTranscription()`
This function handles the partial transcription results received from the server and displays them to the user in real-time.

```html
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Real-Time Transcription</title>
</head>
<body>
  <h1>Real-Time Transcription</h1>
  <div id="transcription"></div>

  <script>
    const transcriptionDiv = document.getElementById('transcription');

    function updateTranscription(transcript) {
      transcriptionDiv.innerHTML += `<p>${transcript}</p>`;
    }

    // Example WebSocket setup to receive partial transcription results
    const socket = new WebSocket('ws://localhost:3000');

    socket.onmessage = function(event) {
      const transcript = JSON.parse(event.data).transcript;
      updateTranscription(transcript);
    };
  </script>
</body>
</html>
```

### Explanation

1. **`makeCall()`**: Initiates an outbound call to the specified phone number.
2. **`handleCallConnect()`**: Sets up the call and starts the transcription stream.
3. **`startTranscriptionStream()`**: Starts the audio stream and sends media data to Google Cloud Speech-to-Text.
4. **`handleMediaData()`**: Processes the media data and sends it to Google Cloud Speech-to-Text for transcription.
5. **`sendPartialTranscription()`**: Sends the partial transcription results to the client.
6. **Client-Side**: Sets up a WebSocket to receive and display the partial transcription results in real-time.

