```javascript
var states = {
    gameplay: {
        create: function() {
            // Create the basket
            basket = game.add.sprite(game.world.centerX, game.world.height - 50, 'basket');
            basket.anchor.setTo(0.5, 1); // Center the basket at the bottom

            // Enable input for the basket
            game.input.keyboard.addKeyCapture([Phaser.Keyboard.LEFT, Phaser.Keyboard.RIGHT]);
            game.input.keyboard.onDownCallback = function(key) {
                if (key.keyCode === Phaser.Keyboard.LEFT) {
                    basket.x -= 50;
                } else if (key.keyCode === Phaser.Keyboard.RIGHT) {
                    basket.x += 50;
                }
            };

            // Create the first fluff ball
            createFluffBall();

            // Create a timer to spawn fluff balls periodically
            game.time.events.loop(Phaser.Timer.SECOND * 0.5, createFluffBall, this);
        }
    }
};

function createFluffBall() {
    // Create a new fluff ball
    var fluffBall = game.add.sprite(
        game.rnd.integerInRange(0, game.world.width),
        0,
        'fluff-ball'
    );
    fluffBall.anchor.setTo(0.5, 0); // Center the fluff ball vertically at the top

    // Add physics to the fluff ball
    game.physics.arcade.enable(fluffBall);
    fluffBall.body.gravity.y = 200;

    // Add the fluff ball to the array
    fluffBalls.push(fluffBall);
}
```

