To avoid hard-coding role names in your code while still leveraging Azure AD for authentication and authorization, you can use dynamic role checks and leverage Azure AD's built-in features. Here’s a step-by-step guide to achieve this:

### Step 1: Define App Roles in Azure AD
1. **Register Your Application in Azure AD:**
   - Go to the Azure portal and navigate to your Azure AD tenant.
   - Register your application and note down the `Application (client) ID`.
   - Navigate to the "API permissions" section and add the necessary API permissions (e.g., `User.Read`, `Directory.Read.All`).

2. **Define App Roles:**
   - Go to the "App registrations" section and select your application.
   - Navigate to the "Manifest" tab.
   - Add app roles to the manifest file. For example:
     ```json
     {
       "appRoles": [
         {
           "allowedMemberTypes": ["User"],
           "description": "Can read Page1",
           "displayName": "Read Page1",
           "id": "your-guid-here",
           "isEnabled": true,
           "value": "read_page1"
         },
         {
           "allowedMemberTypes": ["User"],
           "description": "Can write to Button1",
           "displayName": "Write Button1",
           "id": "your-guid-here",
           "isEnabled": true,
           "value": "write_button1"
         }
       ]
     }
     ```
   - Save the manifest.

### Step 2: Configure Azure AD Authentication in Your ASP.NET MVC Core Application
1. **Install Required NuGet Packages:**
   ```bash
   dotnet add package Microsoft.AspNetCore.Authentication.OpenIdConnect
   dotnet add package Microsoft.Identity.Web
   ```

2. **Configure Authentication in `Startup.cs`:**
   ```csharp
   public void ConfigureServices(IServiceCollection services)
   {
       services.AddAuthentication(options =>
       {
           options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
           options.DefaultChallengeScheme = OpenIdConnectDefaults.AuthenticationScheme;
       })
       .AddCookie()
       .AddMicrosoftIdentityWebApp(Configuration.GetSection("AzureAd"))
       .EnableTokenAcquisitionToCallDownstreamApi()
       .AddInMemoryTokenCaches();

       services.AddControllersWithViews();
       services.AddRazorPages();
   }

   public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
   {
       if (env.IsDevelopment())
       {
           app.UseDeveloperExceptionPage();
       }
       else
       {
           app.UseExceptionHandler("/Home/Error");
           app.UseHsts();
       }

       app.UseHttpsRedirection();
       app.UseStaticFiles();

       app.UseRouting();

       app.UseAuthentication();
       app.UseAuthorization();

       app.UseEndpoints(endpoints =>
       {
           endpoints.MapControllerRoute(
               name: "default",
               pattern: "{controller=Home}/{action=Index}/{id?}");
           endpoints.MapRazorPages();
       });
   }
   ```

3. **Configure Azure AD Settings:**
   In `appsettings.json`, add your Azure AD settings:
   ```json
   {
     "AzureAd": {
       "Instance": "https://login.microsoftonline.com/",
       "Domain": "yourdomain.onmicrosoft.com",
       "TenantId": "your-tenant-id",
       "ClientId": "your-client-id",
       "CallbackPath": "/signin-oidc"
     }
   }
   ```

### Step 3: Implement Dynamic Role Checks in Your Controller Actions
1. **Use `IAuthorizationService` for Dynamic Role Checks:**
   ```csharp
   using Microsoft.AspNetCore.Authorization;
   using Microsoft.AspNetCore.Mvc;

   [Authorize]
   public class HomeController : Controller
   {
       private readonly IAuthorizationService _authorizationService;

       public HomeController(IAuthorizationService authorizationService)
       {
           _authorizationService = authorizationService;
       }

       [Authorize(Policy = "read_page1")]
       public IActionResult Page1()
       {
           var result = _authorizationService.AuthorizeAsync(User, "Page1").Result;
           if (!result.Succeeded)
           {
               return Forbid();
           }
           return View();
       }

       [Authorize(Policy = "write_button1")]
       public IActionResult Button1()
       {
           var result = _authorizationService.AuthorizeAsync(User, "Button1").Result;
           if (!result.Succeeded)
           {
               return Forbid();
           }
           return View();
       }
   }
   ```

2. **Define Policies in `Startup.cs`:**
   ```csharp
   public void ConfigureServices(IServiceCollection services)
   {
       services.AddAuthentication(options =>
       {
           options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
           options.DefaultChallengeScheme = OpenIdConnectDefaults.AuthenticationScheme;
       })
       .AddCookie()
       .AddMicrosoftIdentityWebApp(Configuration.GetSection("AzureAd"))
       .EnableTokenAcquisitionToCallDownstreamApi()
       .AddInMemoryTokenCaches();

       services.AddControllersWithViews(options =>
       {
           options.Filters.Add(new AuthorizeFilter(policy: "RequireRole"));
       });

       services.AddRazorPages();
       services.AddSingleton<IAuthorizationHandler, CustomAuthorizationHandler>();
   }

   public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
   {
       if (env.IsDevelopment())
       {
           app.UseDeveloperExceptionPage();
       }
       else
       {
           app.UseExceptionHandler("/Home/Error");
           app.UseHsts();
       }

       app.UseHttpsRedirection();
       app.UseStaticFiles();

       app.UseRouting();

       app.UseAuthentication();
       app.UseAuthorization();

       app.UseEndpoints(endpoints =>
       {
           endpoints.MapControllerRoute(
               name: "default",
               pattern: "{controller=Home}/{action=Index}/{id?}");
           endpoints.MapRazorPages();
       });
   }
   ```

3. **Create a Custom Authorization Handler:**
   ```csharp
   using System.Security.Claims;
   using System.Threading.Tasks;
   using Microsoft.AspNetCore.Authorization;

   public class CustomAuthorizationHandler : AuthorizationHandler<CustomRequirement>
   {
       protected override Task HandleRequirementAsync(AuthorizationHandlerContext context, CustomRequirement requirement)
       {
           var userClaims = context.User.Claims;
           var appRoles = userClaims.Where(c => c.Type == "roles").Select(c => c.Value).ToList();

           if (appRoles.Contains(requirement.Role))
           {
               context.Succeed(requirement);
           }

           return Task.CompletedTask;
       }
   }

   public class CustomRequirement : IAuthorizationRequirement
   {
       public string Role { get; }

       public CustomRequirement(string role)
       {
           Role = role;
       }
   }
   ```

### Summary
By following these steps, you can dynamically check roles and permissions without hard-coding role names in your code. This approach leverages Azure AD for authentication and authorization, ensuring that your application remains flexible and secure.

