  fadeBetweenImages(images, values);

  // Event listener for the 'S' key press
  document.addEventListener('keydown', (event) => {
    if (event.key === 's' || event.key === 'S') {
      console.log('Stopping updates and keeping the last values.');
      // Prevent further updates
      document.removeEventListener('keydown', (event) => {
        if (event.key === 's' || event.key === 'S') {
          console.log('Stopping updates and keeping the last values.');
        }
      });

      // Keep the last set of values constant
      const lastValues = [...values];
      console.log('Last values:', lastValues);

      // Optionally, you can update the UI with the last values here
      // For example, you can update the canvas with the last values
      fadeBetweenImages(images, lastValues);
    }
  });
});
