```csharp
public void RollGacha()
{
    rollCost = Mathf.RoundToInt(rollCost * Mathf.Pow(costMultiplier, rollCount));
    rollButton.GetComponentInChildren<TextMeshProUGUI>().text = "Roll : " + rollCost;

    if (playerCoins >= rollCost)
    {
        GachaItem item = GetAvailableItem();
        if (item == null)
        {
            resultText.text = "All Items Already Obtained";
            return;
        }
        playerCoins -= rollCost;
        rollCount++;

        // Update the item count and save it to PlayerPrefs
        item.count++;
